    function apTab(t){state.apTab=t;render();window.scrollTo({top:0,behavior:"smooth"})}
    function apSet(k,v){state[k]=v;render()}
    function apDo(fn,...a){try{APX[fn](...a)}catch(_e){}apEnsure().log.unshift({id:"lg-"+Date.now(),at:Date.now(),agent:"billing",title:"يدوي: "+fn,detail:"",sev:1,done:true});persist();render();notify("اتعمل")}
